public void ValidateForCheckout(Order order)
{
    ArgumentNullException.ThrowIfNull(order);
    if (string.IsNullOrWhiteSpace(order.Id)) throw new ArgumentException("Order id is required.", nameof(order));
    if (string.IsNullOrWhiteSpace(order.CustomerId)) throw new ArgumentException("Customer id is required.", nameof(order));
    if (order.Subtotal < 0) throw new ArgumentOutOfRangeException(nameof(order));
    if (order.Status != OrderStatus.Draft) throw new InvalidOperationException("Only draft orders can be checked out.");
}
